        jobs = [job for job in data["jobs"] if job["id"] not in data.get("blocked", [])]
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        best_ids = None
        best_value = None
        k = data["k"]
        for subset in combinations(jobs, k):
            ids = {job["id"] for job in subset}
            if not mandatory.issubset(ids):
                continue
            counts = {}
            for job in subset:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            ordered = sorted(subset, key=lambda job: (job["start"], job["end"], job["id"]))
            if any(ordered[i - 1]["end"] > ordered[i]["start"] for i in range(1, len(ordered))):
                continue
            value = sum(job["value"] for job in subset)
            selected = tuple(sorted(ids))
            if best_value is None or value > best_value or (value == best_value and selected > best_ids):
                best_value, best_ids = value, selected
        if best_ids is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}
    return solve


def _build_component_08():
    def solve(data):
        required = data.get("required", [])
        bits = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)
        source = data["source"]
        initial_mask = bits.get(source, 0)
        start_state = (source, initial_mask, data["coupons"])
        distance = {start_state: data["start"]}
        queue = [(data["start"], source, initial_mask, data["coupons"])]
        while queue:
            arrival, node, mask, remaining = heapq.heappop(queue)
            state = (node, mask, remaining)
            if distance.get(state) != arrival:
                continue
            if node == data["target"] and mask == full and remaining == 0:
                return {"arrival": arrival}
            for edge in graph[node]:
                depart = max(arrival, edge["open"])
                if depart >= edge["close"]:
                    continue
                choices = [(edge["duration"], remaining)]
                if remaining:
                    choices.append((max(1, edge["duration"] - edge.get("discount", 0)), remaining - 1))
                for duration, next_remaining in choices:
                    next_time = depart + duration
                    if next_time > data["deadline"]:
                        continue
                    next_node = edge["v"]
                    next_mask = mask | bits.get(next_node, 0)
                    next_state = (next_node, next_mask, next_remaining)
                    if next_time < distance.get(next_state, float("inf")):
                        distance[next_state] = next_time
                        heapq.heappush(queue, (next_time, next_node, next_mask, next_remaining))
        return {"arrival": None}
    return solve


